-- R8 audited work-queue item persistence.
CREATE OR REPLACE FUNCTION public.mmhr_record_work_item(payload jsonb, correlation_id uuid, idempotency_key uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE context record; receipt jsonb; item public.work_items%ROWTYPE; v_org uuid; v_actor uuid; v_id uuid; v_action text; v_expected text; v_status text; v_queue text; v_role text; v_priority text; v_due timestamptz; v_reminder timestamptz; v_escalated boolean;
BEGIN
 IF jsonb_typeof(payload)<>'object' OR coalesce(payload->>'action','') NOT IN ('create','update') OR coalesce(payload->>'taskId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'organizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'actorIdentityId','') !~ '^[0-9a-fA-F-]{36}$' OR correlation_id IS NULL OR idempotency_key IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid work item input'; END IF;
 v_org:=(payload->>'organizationId')::uuid; v_actor:=(payload->>'actorIdentityId')::uuid; v_id:=(payload->>'taskId')::uuid; v_action:=payload->>'action'; SELECT * INTO context FROM mmhr_private.r1_start_security_command('workspace.access',v_org,'Record work item',correlation_id,idempotency_key); IF v_actor<>context.actor_identity_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Security command denied'; END IF; receipt:=mmhr_private.r1_checked_receipt(context.actor_identity_id,'r8.work_item',idempotency_key,payload); IF receipt IS NOT NULL THEN RETURN jsonb_build_object('taskId',receipt->>'entity_id','organizationId',v_org,'outcomeCode','replayed','correlationId',correlation_id); END IF;
 IF v_action='create' THEN
   IF payload->>'queue' NOT IN ('approvals','follow_ups','scheduling','commissions','onboarding_risks') OR payload->>'assignedRole' NOT IN ('super_admin','admin','advisor','sales','finance','operations','support') OR payload->>'status' NOT IN ('open','in_progress','blocked','completed','cancelled') OR payload->>'priority' NOT IN ('low','normal','high','urgent') OR coalesce(payload->>'createdAt','')='' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid work item create'; END IF;
   v_queue:=payload->>'queue'; v_role:=payload->>'assignedRole'; v_status:=payload->>'status'; v_priority:=payload->>'priority'; v_due:=NULLIF(payload->>'dueAt','')::timestamptz; v_reminder:=NULLIF(payload->>'reminderAt','')::timestamptz; v_escalated:=coalesce((payload->>'escalated')::boolean,false); IF v_reminder IS NOT NULL AND v_reminder< (payload->>'createdAt')::timestamptz THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Reminder precedes creation'; END IF; IF v_status IN ('completed','cancelled') AND v_escalated THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Closed work cannot be escalated'; END IF;
   INSERT INTO public.work_items(id,organization_id,queue,assigned_role,assignee_identity_id,status,priority,due_at,reminder_at,escalated,created_at,updated_at) VALUES(v_id,v_org,v_queue,v_role,NULLIF(payload->>'assigneeIdentityId','')::uuid,v_status,v_priority,v_due,v_reminder,v_escalated,(payload->>'createdAt')::timestamptz,clock_timestamp()) RETURNING * INTO item;
 ELSE
   v_expected:=payload->>'expectedStatus'; SELECT * INTO item FROM public.work_items WHERE id=v_id AND organization_id=v_org FOR UPDATE; IF NOT FOUND OR item.status<>v_expected THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Work item update denied'; END IF;
   v_status:=coalesce(payload->>'status',item.status); v_priority:=coalesce(payload->>'priority',item.priority); v_escalated:=coalesce((payload->>'escalated')::boolean,item.escalated); IF v_status NOT IN ('open','in_progress','blocked','completed','cancelled') OR v_priority NOT IN ('low','normal','high','urgent') OR (v_status IN ('completed','cancelled') AND v_escalated) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid work item update'; END IF;
   UPDATE public.work_items SET status=v_status,priority=v_priority,assignee_identity_id=coalesce(NULLIF(payload->>'assigneeIdentityId','')::uuid,assignee_identity_id),due_at=coalesce(NULLIF(payload->>'dueAt','')::timestamptz,due_at),reminder_at=coalesce(NULLIF(payload->>'reminderAt','')::timestamptz,reminder_at),escalated=v_escalated,updated_at=clock_timestamp() WHERE id=v_id AND organization_id=v_org RETURNING * INTO item;
 END IF;
 PERFORM mmhr_private.r1_finish_security_command(context.actor_identity_id,'r8.work_item','work_item.'||v_action,'work_item',item.id,v_org,'Record work item',correlation_id,idempotency_key,payload,jsonb_build_object('status','completed'),jsonb_build_object('status','completed'),context.authorization_time);
 RETURN jsonb_build_object('taskId',item.id,'organizationId',item.organization_id,'status',item.status,'outcomeCode','recorded','correlationId',correlation_id);
END; $$;
REVOKE ALL ON FUNCTION public.mmhr_record_work_item(jsonb,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role,mmhr_worker; GRANT EXECUTE ON FUNCTION public.mmhr_record_work_item(jsonb,uuid,uuid) TO authenticated;
